import java.util.concurrent.atomic.AtomicReference

final case class Balances(version: Long, map: Map[String, Long])

sealed trait TxResult[+A]; case class TxOk[A](value: A) extends TxResult[A]
case class TxConflict() extends TxResult[Nothing]

final class Txn(state: AtomicReference[Balances]) {
  def run[A](body: Balances => A): TxResult[A] = {
    val cur = state.get()                 // one read = the snapshot
    body(cur) match {
      case TxConflict() => TxConflict()   // block says it cannot proceed: replay
      case result =>
        val next = cur.copy(version = cur.version + 1)
        if (state.compareAndSet(cur, next)) TxOk(result) else TxConflict()
    }
  }
}
